            p.error(
                f'--model-aliases: malformed pair {pair!r}; '
                'expected alias:model format'
            )
        alias, model = parts[0].strip(), parts[1].strip()
        if not alias:
            p.error(
                f'--model-aliases: alias in pair {pair!r} '
